mapper.select:
select max(created_at) as last_load
from ${table}
where deal_year = #{dealYear} and deal_month = #{dealMonth}

mapper.sql:
where t.sgg_cd = #{sggCd}
  and t.apt_seq = #{aptSeq}

    and t.umd_nm = #{umdNm}

mapper.select:
select t.apt_seq, t.apt_nm, t.umd_nm, min(t.jibun) as jibun, max(t.build_year) as build_year, count(*) as deal_count, max(t.deal_year * 100 + t.deal_month) as last_ym, round(avg(t.deal_amount)) as avg_amount from estate.apt_trade t where t.sgg_cd = #{sggCd}
and t.umd_nm = #{umdNm}
and t.apt_nm ilike '%' || #{keyword} || '%'
group by t.apt_seq, t.apt_nm, t.umd_nm order by count(*) desc limit #{limit}

select t.deal_year, t.deal_month, t.deal_year * 100 + t.deal_month as ym, count(*) as deal_count, round(avg(t.deal_amount)) as avg_amount, percentile_cont(0.5) within group (order by t.deal_amount) as median_amount, min(t.deal_amount) as min_amount, max(t.deal_amount) as max_amount, round(avg(t.exclu_use_ar), 2) as avg_area, round(avg(t.deal_amount / nullif(t.exclu_use_ar, 0)), 1) as avg_amount_per_m2 from estate.apt_trade t
and round(t.exclu_use_ar / 3.3058 / 0.75) = #{pyeong}
group by t.deal_year, t.deal_month order by ym

select t.deal_year, t.deal_month, t.deal_year * 100 + t.deal_month as ym, count(*) as deal_count, count(*) filter (where coalesce(t.monthly_rent, 0) = 0) as jeonse_count, count(*) filter (where coalesce(t.monthly_rent, 0) > 0) as wolse_count, round(avg(t.deposit) filter (where coalesce(t.monthly_rent, 0) = 0)) as avg_jeonse_deposit, round(avg(t.deposit) filter (where coalesce(t.monthly_rent, 0) > 0)) as avg_wolse_deposit, round(avg(t.monthly_rent) filter (where coalesce(t.monthly_rent, 0) > 0)) as avg_monthly_rent, round(avg(t.exclu_use_ar), 2) as avg_area from estate.apt_rent t where t.sgg_cd = #{sggCd} and t.apt_seq = #{aptSeq}
and t.umd_nm = #{umdNm}
and round(t.exclu_use_ar / 3.3058 / 0.75) = #{pyeong}
group by t.deal_year, t.deal_month order by ym

select t.deal_year, t.deal_month, t.deal_day, t.exclu_use_ar, t.floor, t.apt_dong, round(t.exclu_use_ar / 3.3058 / 0.75) as pyeong, t.deal_amount, t.dealing_gbn, t.cdeal_type, round(t.deal_amount / nullif(t.exclu_use_ar, 0), 1) as amount_per_m2 from estate.apt_trade t
and round(t.exclu_use_ar / 3.3058 / 0.75) = #{pyeong}
order by t.deal_year desc, t.deal_month desc, t.deal_day desc, t.deal_amount desc limit #{limit}

select t.sgg_cd, coalesce(g.sgg_nm, t.sgg_cd) as sgg_nm, t.umd_nm, t.apt_nm, t.apt_dong, t.jibun, t.exclu_use_ar, t.floor, t.build_year, t.deal_year, t.deal_month, t.deal_day, t.deal_amount, t.dealing_gbn, t.cdeal_type, round(t.deal_amount / nullif(t.exclu_use_ar, 0), 1) as amount_per_m2 from estate.apt_trade t left join public.g_sgg g on g.sgg_cd = t.sgg_cd where 1 = 1
and t.sgg_cd = #{sggCd}
and t.umd_nm = #{umdNm}
and t.apt_nm ilike '%' || #{aptNm} || '%'
order by t.deal_year desc, t.deal_month desc, t.deal_day desc, t.deal_amount desc limit #{limit}

select t.sgg_cd, coalesce(g.sgg_nm, t.sgg_cd) as sgg_nm, count(*) as deal_count, round(avg(t.deal_amount)) as avg_amount, round(avg(t.deal_amount / nullif(t.exclu_use_ar, 0)), 1) as avg_amount_per_m2 from estate.apt_trade t left join public.g_sgg g on g.sgg_cd = t.sgg_cd where t.deal_amount is not null
and t.sgg_cd between #{sidoCd} || '000' and #{sidoCd} || '999'
group by t.sgg_cd, g.sgg_nm having count(*) >= 10 order by avg_amount desc limit #{limit}
